async function main() {
  console.log("Seeding public website content...");

  await db.examPage.deleteMany();
  await db.coursePage.deleteMany();
  await db.universityPage.deleteMany();
  await db.countryPage.deleteMany();

  // Countries
  for (const c of countries) {
    await db.countryPage.create({
      data: {
        slug: c.slug, name: c.name, shortName: c.shortName, flag: c.flag, capital: c.capital, currency: c.currency, intro: c.intro,
        quickFacts: J(c.quickFacts), whyStudy: J(c.whyStudy), pathway: J(c.pathway), popularCourses: J(c.popularCourses),
        entryRequirements: J(c.entryRequirements), documents: J(c.documents), visaProcess: J(c.visaProcess),
        interviewTypes: J(c.interviewTypes), workRights: J(c.workRights), scholarships: J(c.scholarships),
        cities: J(c.cities), faqs: J(c.faqs),
        sourceUrl: c.sourceUrl, lastVerifiedAt: NOW, verificationStatus: "VERIFIED", approvalStatus: "PUBLISHED",
      },
    });
  }
  console.log(`Seeded ${countries.length} country pages`);

  // Universities
  for (const u of universities) {
    await db.universityPage.create({
      data: {
        slug: u.slug, name: u.name, countrySlug: u.countrySlug, city: u.city, overview: u.overview,
        strengths: J(u.strengths), quickFacts: J(u.quickFacts), entryRequirements: J(u.entryRequirements),
        tuition: J(u.tuition), applicationSteps: J(u.applicationSteps), documents: J(u.documents), faqs: J(u.faqs),
        sourceUrl: u.sourceUrl, lastVerifiedAt: NOW, verificationStatus: "VERIFIED", approvalStatus: "PUBLISHED",
      },
    });
  }
  console.log(`Seeded ${universities.length} university pages`);

  // Courses
  for (const c of courses) {
    await db.coursePage.create({
      data: {
        slug: c.slug, name: c.name, universitySlug: c.universitySlug, countrySlug: c.countrySlug, city: c.city,
        level: c.level, subject: c.subject, duration: c.duration, intake: c.intake, tuition: c.tuition,
        scholarship: c.scholarship, englishRequirement: c.englishRequirement, academicRequirement: c.academicRequirement,
        overview: c.overview, modules: J(c.modules), careerOutcomes: J(c.careerOutcomes), documents: J(c.documents),
        faqs: J(c.faqs), deadline: c.deadline, sourceUrl: c.sourceUrl, lastVerifiedAt: NOW, verificationStatus: "VERIFIED", approvalStatus: "PUBLISHED",
      },
    });
  }
  console.log(`Seeded ${courses.length} course pages`);

  // Exams
  for (const e of exams) {
    await db.examPage.create({
      data: {
        slug: e.slug, name: e.name, fullName: e.fullName, intro: e.intro, whatIs: e.whatIs,
        modules: J(e.modules), mockRules: J(e.mockRules), freeQuota: J(e.freeQuota), examExperience: J(e.examExperience),
        aiScoring: J(e.aiScoring), speakingPractice: J(e.speakingPractice), writingReview: J(e.writingReview),
        resultReport: J(e.resultReport), pricing: J(e.pricing), faqs: J(e.faqs), disclaimer: e.disclaimer,
        sourceUrl: e.sourceUrl || null, lastVerifiedAt: NOW, verificationStatus: "VERIFIED", approvalStatus: "PUBLISHED",
      },
    });
  }
  console.log(`Seeded ${exams.length} exam pages`);

  console.log("Public content seed complete!");
  console.log(`Countries: ${await db.countryPage.count()}, Universities: ${await db.universityPage.count()}, Courses: ${await db.coursePage.count()}, Exams: ${await db.examPage.count()}`);
}

main().catch((e) => { console.error(e); process.exit(1); }).finally(async () => { await db.$disconnect(); });
